def convert_base(number: str, from_base: int, to_base: int) -> str:
    # Validate bases
    if not (2 <= from_base <= 36) or not (2 <= to_base <= 36):
        raise ValueError(f"Bases must be between 2 and 36. Got from_base={from_base}, to_base={to_base}")

    # Validate number string
    if not number or number == "-":
        raise ValueError("Number string cannot be empty or just '-'")

    # Normalize input: strip whitespace (not specified but good practice), handle sign
    is_negative = number.startswith("-")
    if is_negative:
        number = number[1:]

    if not number:
        raise ValueError("Number string cannot be empty or just '-'")

    # Check for invalid characters for the given from_base
    valid_chars = "0123456789abcdefghijklmnopqrstuvwxyz"
    char_to_val = {c: i for i, c in enumerate(valid_chars)}

    for char in number:
        if char not in char_to_val:
            raise ValueError(f"Invalid character '{char}' for base {from_base}")
        if char_to_val[char] >= from_base:
            raise ValueError(f"Digit '{char}' is invalid for base {from_base}")

    # Convert from from_base to base 10 (internal integer)
    value = 0
    for char in number:
        digit_val = char_to_val[char.lower()]
        value = value * from_base + digit_val

    # Handle zero
    if value == 0:
        return "0"

    # Handle negative numbers
    if is_negative:
        value = -value

    # Convert from base 10 to to_base
    if value < 0:
        result_chars = []
        value = -value
        while value > 0:
            remainder = value % to_base
            result_chars.append(valid_chars[remainder])
            value //= to_base
        result = "".join(reversed(result_chars))
        return "-" + result
    else:
        result_chars = []
        while value > 0:
            remainder = value % to_base
            result_chars.append(valid_chars[remainder])
            value //= to_base
        result = "".join(reversed(result_chars))
        return result
