    let decodedKey = key.replace(/\+/g, ' ');
    let decodedValue = value.replace(/\+/g, ' ');

    // Percent-decode (case-insensitive, handles %XX sequences)
    // If decoding fails or produces invalid sequences, we keep the original text 
    // but with '+' already converted to space.
