      // So we keep the string with spaces where + was, and the % sequences as they were (invalid).
      // We do not revert the + replacement.
      // But decodeURIComponent might have partially decoded? No, it throws on invalid.
      // So we just use the pre-decode string (with + replaced).
      // Wait, decodeURIComponent throws if there is an invalid sequence.
      // So we catch the error and use the string that had + replaced.
      // We do NOT try to decode partially.
    }

    // Check if key is a prototype pollution attempt
    const isPrototype = key === '__proto__' || key === 'constructor' || key === 'prototype';

    if (!map.has(key)) {
      map.set(key, { values: [], isPrototype: isPrototype });
