      // but we must ensure we don't accidentally set Object.prototype.
      // Since we are building a new object at the end, we can just store the raw key string.
      // The only risk is if we do Object.create(null) vs regular object.
      // We will build a regular object but set the property explicitly.
    }

    entry.values.push(decodedValue);
