      // Explicitly set as own property to avoid prototype pollution
      Object.defineProperty(result, key, {
        value: values[0],
        writable: true,
        enumerable: true,
        configurable: true
      });
    } else {
      // Multiple values
      Object.defineProperty(result, key, {
        value: values,
        writable: true,
        enumerable: true,
        configurable: true
      });
    }
  }

  return result;
