/**
 * Deep equality check supporting cyclic structures.
 * Uses SameValueZero semantics for primitives.
 */

export function deepEqual(a, b) {
  const cache = new WeakMap();

  function isEqual(a, b) {
    // SameValueZero check for primitives
    if (a === b) return true;
    if (typeof a !== 'object' || a === null || typeof b !== 'object' || b === null) {
      return false;
    }

    // Handle cyclic structures
    const aStack = cache.get(a);
    const bStack = cache.get(b);

    if (aStack) {
      if (!bStack) return false;
      return isEqual(aStack, bStack);
    }
    if (bStack) {
      return false;
    }

    // Mark as visiting
    cache.set(a, b);
    cache.set(b, a);

    const aIsDate = a instanceof Date;
    const bIsDate = b instanceof Date;

    if (aIsDate !== bIsDate) {
      cache.delete(a);
      cache.delete(b);
      return false;
    }

    if (aIsDate) {
      return a.getTime() === b.getTime();
    }

    const aIsArray = Array.isArray(a);
    const bIsArray = Array.isArray(b);

    if (aIsArray !== bIsArray) {
      cache.delete(a);
      cache.delete(b);
      return false;
    }

    // Arrays
    if (aIsArray) {
      if (a.length !== b.length) {
        cache.delete(a);
        cache.delete(b);
        return false;
      }
      for (let i = 0; i < a.length; i++) {
        if (!isEqual(a[i], b[i])) {
          cache.delete(a);
          cache.delete(b);
          return false;
        }
      }
    } else {
      // Objects
      const aKeys = Object.keys(a);
      const bKeys = Object.keys(b);

      if (aKeys.length !== bKeys.length) {
        cache.delete(a);
        cache.delete(b);
        return false;
      }

      // Compare values for each key in 'a'
      for (const key of aKeys) {
        if (!b.hasOwnProperty(key)) {
          cache.delete(a);
          cache.delete(b);
          return false;
        }
        if (!isEqual(a[key], b[key])) {
          cache.delete(a);
          cache.delete(b);
          return false;
        }
      }
    }

    // Clear cache for this branch
    cache.delete(a);
    cache.delete(b);
    return true;
  }

  return isEqual(a, b);
}
