      pos++; // consume '('
      const result = parseUnary();
      if (pos >= len || expression[pos] !== ')') {
        throw new SyntaxError('Expected closing parenthesis');
      }
      pos++; // consume ')'
      return result;
    }
    return parseNumber();
  };

  const parseUnaryExpr = () => {
    return parseUnary();
  };

  const parseMulDiv = (left) => {
    skipWhitespace();
    while (true) {
      if (expression[pos] === '*') {
        pos++;
        const right = parseUnaryExpr();
        left = left * right;
      } else if (expression[pos] === '/') {
        pos++;
        const right = parseUnaryExpr();
        if (right === 0) {
