    return left;
  };

  const parseAddSub = (left) => {
    skipWhitespace();
    while (true) {
      if (expression[pos] === '+') {
        pos++;
        const right = parseUnaryExpr();
        left = left + right;
      } else if (expression[pos] === '-') {
        pos++;
        const right = parseUnaryExpr();
        left = left - right;
      } else {
