/**
 * Finds the first and last index of a target value in a sorted array.
 * Uses binary search to achieve O(log n) time complexity.
 * 
 * @param {number[]} sorted - An array of numbers sorted in ascending order.
 * @param {number} target - The number to find.
 * @returns {[number, number]} An array [first, last] containing the indices, 
 *                             or [-1, -1] if the target is not found.
 */
export function searchRange(sorted, target) {
  // Helper: Binary search to find the leftmost (first) occurrence
  function findLeft(arr, target) {
    let left = 0;
    let right = arr.length - 1;

    while (left <= right) {
      const mid = (left + right) >> 1; // Bitwise shift for division by 2

      if (arr[mid] < target) {
        left = mid + 1;
      } else if (arr[mid] > target) {
        right = mid - 1;
      } else {
        // arr[mid] == target, try to find a smaller index
        right = mid - 1;
      }
    }

    // Check if the index is valid and matches the target
    if (left < arr.length && arr[left] === target) {
      return left;
    }
    return -1;
  }

  // Helper: Binary search to find the rightmost (last) occurrence
  function findRight(arr, target) {
    let left = 0;
    let right = arr.length - 1;

    while (left <= right) {
      const mid = (left + right) >> 1;

      if (arr[mid] < target) {
        left = mid + 1;
      } else if (arr[mid] > target) {
        right = mid - 1;
      } else {
        // arr[mid] == target, try to find a larger index
        left = mid + 1;
      }
    }

    // Check if the index is valid and matches the target
    if (right >= 0 && arr[right] === target) {
      return right;
    }
    return -1;
  }

  const first = findLeft(sorted, target);

  // If target is not found, return [-1, -1]
  if (first === -1) {
    return [-1, -1];
  }

  const last = findRight(sorted, target);
  return [first, last];
