    def parse_ident(s: str):
        if s.isdigit():
            return ("numeric", int(s))
        return ("alphanumeric", s)

    # Helper to compare two lists of identifiers
    def compare_ids(ids_a, ids_b):
        # If a has fewer identifiers and they match up to len(a), a is lower
        for i in range(max(len(ids_a), len(ids_b))):
            if i >= len(ids_a):
                return -1  # a is shorter, so lower precedence
            if i >= len(ids_b):
                return 1   # b is shorter, so a is higher precedence
            type_a, val_a = ids_a[i]
            type_b, val_b = ids_b[i]
            # Numeric identifiers have lower precedence than alphanumeric ones
            if type_a != type_b:
                if type_a == "numeric":
                    return -1
                else:
                    return 1
            # Same type: compare values
            if val_a < val_b:
                return -1
            if val_a > val_b:
                return 1
        return 0

    # Split into core, prerelease, build
    def parse_ver(v: str):
        core = v.split("-", 1)[0]
        pre = v[len(core):].split("+", 1)[0] if "-" in v else ""
        build = v.split("+", 1)[1] if "+" in v else ""
        core_parts = core.split(".")
        # Parse prerelease identifiers
        pre_ids = []
        if pre:
            for p in pre.split("."):
                pre_ids.append(parse_ident(p))
        # Build is ignored, but we still parse it to ensure it doesn't break logic (not used in comparison)
        # We don't parse build identifiers, just ignore.
        return core_parts, pre_ids

    core_a, pre_a = parse_ver(a)
    core_b, pre_b = parse_ver(b)

    # Compare numeric core parts
    for i in range(3):
        try:
            n_a = int(core_a[i])
            n_b = int(core_b[i])
        except ValueError:
            # Should not happen for valid SemVer, but if it does, treat as alphanumeric
            # However, SemVer core must be numeric, so we assume valid input.
            n_a, n_b = core_a[i], core_b[i]
            if n_a < n_b:
                return -1
            if n_a > n_b:
                return 1
        if n_a < n_b:
            return -1
        if n_a > n_b:
