    teens = {
        11: "eleven", 12: "twelve", 13: "thirteen", 14: "fourteen", 15: "fifteen",
        16: "sixteen", 17: "seventeen", 18: "eighteen", 19: "nineteen"
    }
    tens = {
        2: "twenty", 3: "thirty", 4: "forty", 5: "fifty", 6: "sixty",
        7: "seventy", 8: "eighty", 9: "ninety"
    }
    ones = {
        1: "one", 2: "two", 3: "three", 4: "four", 5: "five",
        6: "six", 7: "seven", 8: "eight", 9: "nine", 0: ""
    }

    def _words_under_100(num: int) -> str:
        if num == 0:
            return ""
        if num < 20:
            return teens.get(num, ones[num])
        ten = num // 10
        one = num % 10
        if one == 0:
            return tens[ten]
        return f"{tens[ten]}-{ones[one]}"

    def _words_under_1000(num: int) -> str:
        if num == 0:
            return ""
        hundred = num // 100
        remainder = num % 100
        if remainder == 0:
            return ones[hundred] + " hundred"
        return f"{ones[hundred]} hundred {_words_under_100(remainder)}"

    if n == 0:
        return "zero"

    scales = [
        (999_000_000_000, "billion"),
        (1_000_000, "million"),
        (1_000, "thousand")
    ]

    parts = []
    for scale_val, scale_name in scales:
        chunk = (n // scale_val) % 1000
        if chunk > 0:
            parts.append(_words_under_1000(chunk) + " " + scale_name)

    return " ".join(parts)
