/**
 * Parses a URL query string into a plain object.
 * 
 * Rules:
 * - Optional leading "?".
 * - Pairs separated by "&"; empty pairs ignored.
 * - Split on first "="; key without "=" -> "".
 * - "+" -> space; then percent-decode. If decoding fails, keep text as-is (with spaces from '+').
 * - Duplicate keys -> array of values.
 * - Safe against prototype pollution (__proto__ becomes own property).
 */
export function parseQuery(query) {
    // Remove leading "?" if present
    const clean = query && query[0] === "?" ? query.slice(1) : query;

    const result = Object.create(null); // Ensure no prototype pollution

    if (!clean) return result;

    const pairs = clean.split("&");

    for (const pair of pairs) {
        if (!pair) continue; // Ignore empty pairs

        // Split on the first "="
        const idx = pair.indexOf("=");
        let key, value;

        if (idx === -1) {
            key = pair;
            value = "";
        } else {
            key = pair.slice(0, idx);
            value = pair.slice(idx + 1);
        }

        // Decode '+' as space
        let decodedKey = key.replace(/\+/g, " ");
        let decodedValue = value.replace(/\+/g, " ");

        // Percent-decode (only for ASCII 00-FF)
        // If decoding fails or produces invalid chars, keep as-is
        try {
            decodedKey = decodeURIComponent(decodedKey);
            decodedValue = decodeURIComponent(decodedValue);
        } catch {
            // If decoding fails (e.g., %XX where XX is invalid hex), keep original
            // But we already replaced '+' with spaces, so keep that text as-is.
            decodedKey = key;
            decodedValue = value;
        }

        // Handle duplicate keys
        if (decodedKey in result) {
            if (!Array.isArray(result[decodedKey])) {
                result[decodedKey] = [result[decodedKey]];
            }
            result[decodedKey].push(decodedValue);
        } else {
            result[decodedKey] = decodedValue;
        }
    }

    return result;
}
