export function deepEqual(a, b) {
  if (a === b) {
    // SameValueZero: NaN === NaN, -0 === 0, primitives equal
    return true;
  }

  // Handle object types
  const typeA = typeof a;
  const typeB = typeof b;

  if (typeA !== typeB) {
    return false;
  }

  if (typeA === 'object') {
    if (a === null || b === null) {
      return false;
    }

    const isArrayA = Array.isArray(a);
    const isArrayB = Array.isArray(b);

    if (isArrayA !== isArrayB) {
      return false;
    }

    if (isArrayA) {
      if (a.length !== b.length) {
        return false;
      }
      for (let i = 0; i < a.length; i++) {
        if (!deepEqual(a[i], b[i])) {
          return false;
        }
      }
      return true;
    } else {
      // Plain objects: compare own enumerable string keys
      const keysA = Object.keys(a);
      const keysB = Object.keys(b);

      if (keysA.length !== keysB.length) {
        return false;
      }

      const keySetA = new Set(keysA);
      for (const key of keysB) {
        if (keySetA.has(key) === false) {
          return false;
        }
        if (!deepEqual(a[key], b[key])) {
          return false;
        }
      }
      return true;
    }
  }

  // For Date objects, compare time values directly
  if (typeA === 'object' && a instanceof Date && b instanceof Date) {
    return a.getTime() === b.getTime();
  }

  return false;
}
