    throw new TypeError('expression must be a string');
  }

  // Tokenize
  const tokens = tokenize(expression);
  let pos = 0;

  function peek() {
    return tokens[pos] || null;
  }

  function consume() {
    return tokens[pos++];
  }

  // Parse expression: addition/subtraction
  function parseExpression() {
    let left = parseTerm();
    while (peek() === '+' || peek() === '-') {
      const op = consume();
      const right = parseTerm();
      left = op === '+' ? left + right : left - right;
    }
    return left;
  }

  // Parse term: multiplication/division
  function parseTerm() {
    let left = parseUnary();
    while (peek() === '*' || peek() === '/') {
      const op = consume();
      const right = parseUnary();
      if (op === '/' && right === 0) {
        throw new RangeError('Division by zero');
      }
      left = op === '*' ? left * right : left / right;
    }
    return left;
  }

  // Parse unary: + or - or number or parenthesized expression
  function parseUnary() {
    if (peek() === '+') {
      consume();
      return parseUnary(); // unary plus is identity, but we must parse the next token
    }
    if (peek() === '-') {
      consume();
      return -parseUnary(); // unary minus
    }
    return parsePrimary();
  }

  // Parse primary: number or parenthesized expression
  function parsePrimary() {
    const token = peek();
    if (token === null) {
      throw new SyntaxError('Unexpected end of input');
    }

    if (token === '(') {
      consume();
      const value = parseExpression();
      if (peek() !== ')') {
        throw new SyntaxError('Missing closing parenthesis');
      }
      consume();
      return value;
    }

    // Must be a number
    if (token === null) {
      throw new SyntaxError('Unexpected end of input');
    }

    // Check if it's a valid number token (digits and optional decimal point)
    if (!/^[0-9]*\.?[0-9]+$/.test(token)) {
      throw new SyntaxError('Invalid character in expression');
    }

    const num = parseFloat(token);
    if (isNaN(num)) {
      throw new SyntaxError('Invalid number');
    }
    consume();
    return num;
  }

  const result = parseExpression();

  // Ensure all tokens are consumed
  if (pos < tokens.length) {
    throw new SyntaxError('Unexpected token after expression');
  }

  return result;
