// Tokenizer
function tokenize(input) {
  const tokens = [];
  let i = 0;
  const len = input.length;

  while (i < len) {
    const ch = input[i];

    // Skip whitespace
    if (ch <= ' ') {
      i++;
      continue;
    }

    // Parentheses
    if (ch === '(' || ch === ')') {
      tokens.push(ch);
      i++;
      continue;
    }

    // Operators
    if (ch === '+' || ch === '-' || ch === '*' || ch === '/') {
      tokens.push(ch);
      i++;
      continue;
    }

    // Number (including decimals)
    if (/[0-9]/.test(ch) || ch === '.') {
      let j = i;
      // Digits
      while (j < len && /[0-9]/.test(input[j])) {
        j++;
      }
      // Decimal point
      if (input[j] === '.') {
        j++;
        while (j < len && /[0-9]/.test(input[j])) {
          j++;
        }
      }
      // We must have at least one digit before or after the dot
      if (j === i) {
        throw new SyntaxError('Invalid number format');
      }
      tokens.push(input.slice(i, j));
      i = j;
      continue;
    }

    // Unknown character
    throw new SyntaxError(`Unexpected character: ${ch}`);
  }

  return tokens;
}
